import type { CloseReading, InlineGlossary } from '../types/closeReading';
import type { ReadingQuestion } from '../types/readingQuestion';
import { cet4CommonInlineGlossaryWords } from './cet4CommonInlineGlossary';

const close = (text: string, translation: string): CloseReading => ({
  translation, vocabulary: [],
  structure: { pattern: '段落整体理解', explanation: '本段以完整信息块呈现，先整体把握主旨，再结合上下文理解细节。' },
  highlights: [{ role: 'complement', text }],
});

const question = (number: number, prompt: string, answer: 'A' | 'B' | 'C' | 'D', evidence: string, options: readonly [string, string][]): ReadingQuestion => ({
  number, prompt, answer, evidence,
  analysis: `原文指出“${evidence}”，因此第 ${number} 题选择 ${answer}。`,
  closeReading: close(prompt, `题目要求判断：${prompt}`),
  options: options.map(([key, text]) => ({ key: key as 'A' | 'B' | 'C' | 'D', text, explanation: key === answer ? '该选项与原文依据相符。' : '该选项与原文依据不符。' })),
});

const clozeSentences = [
  "Psychologists have long been interested in how we construct our identities and the sorts of strategies that we use to present ourselves in society.",
  "New findings suggest that the kinds of complex and strategic self-presentation behaviour we see in adults appear at a much younger age than previously known.",
  "Research shows that a child's awareness of social standing comes from adults.",
  "Like grown-ups, kids want to be accepted by those they admire.",
  "Interactive experiences may provide opportunities for children to learn about what constitutes a desirable reputation and the kinds of strategies that are effective for building a good reputation in their social environment.",
  "Five-year-olds aren't just aware of their reputations, they also behave strategically to alter their outward image.",
  "They will vary their behaviour in order to appear moral or socially good in the eyes of key observers.",
  "While we know that adults use a large variety of attributes to manage and create impressions, we don't yet know whether children understand and use the fact that different attributes are valuable at different times to different audiences.",
  "It's important for us to further consider where in this process children succeed in controlling their reputation and where they struggle.",
  "A question to think about is, \"What happens even earlier than age five?\"",
  "Children don't just show up to the first day of kindergarten and have the idea of reputation pop suddenly into existence.",
  "The logical question to ask is, \"What happens even earlier?\"",
] as const;

const passageOneSentences = [
  "New research suggests that pandas may be at risk of dying out because they are too comfortable.",
  "Experts say too much happiness can stop the bears from searching for new mates.",
  "Environmentalists have long believed that building roads or homes near the bears may threaten their survival by \"reducing or fragmenting their natural habitats\", The Times reported.",
  "But the new research suggests that a \"modest degree of discomfort and fragmentation\" may actually help preserve panda populations.",
  "The research was conducted by scientists from Michigan State University.",
  "It concluded that pandas fail to wander off in search of new mates if they find their habitat too comfortable, resulting in a lack of vital genetic diversity.",
  "For their study—outlined in a paper in the journal Conservation Biology—the team looked at genetic diversity and spread among a Chinese panda population.",
  "The ideal level of perfectly livable habitat was found to be only 80% of an area, with the remainder either too harsh or too affected by human activity.",
  "The experts concluded that pandas should ideally \"be happy enough to thrive, but not so content that they don't want to move around and find new mates\".",
  "Their conclusions about what The Guardian described as this \"sweet spot\" are in line with the so-called Goldilocks principle: that there can be just the right amount of something.",
  "The concept has been applied to a wide range of disciplines, from developmental psychology to economics and engineering.",
  "Claudio Sillero, a professor of conservation biology at Oxford University, told the newspaper that the new findings could have implications beyond panda conservation.",
  "\"Most large animals that eat meat live in increasingly fragmented landscapes,\" said Sillero, who was not involved in the research.",
  "\"It may well be that the messy nature of their relationship with human efforts induces more animals to scatter or travel further, and might result in greater genetic connectivity and enhanced population persistence.\"",
  "The most recent count of pandas found that there were more than 1,800 left in the wild, putting them on the list of vulnerable, but not endangered, species.",
] as const;

const passageTwoSentences = [
  "With those born with natural talents, it feels as if they excel without really trying.",
  "But what about those of us who don't have a natural talent?",
  "We've been told all our lives that if you work hard, you too can succeed.",
  "But with the release of Angela Duckworth's Grit, we are given a new key to success.",
  "\"As much as talent counts, effort counts twice,\" says Duckworth in Grit.",
  "She introduces a new concept that talent may be overrated, and if you want real success, what you need is grit, the perfect combination of passion and persistence.",
  "Even if you have natural talent, it's nothing without grit.",
  "Duckworth says grit is the difference between success and failure.",
  "A person who has grit is more likely to succeed than a person who does not.",
  "When we think about attaining success—whether it's landing that job or learning that new skill—our thoughts are immediately burdened by all the things we must first learn.",
  "If you want that new job, you have to learn the job skills, then the interview skills, then the dress part—and you must be perfect at all of them.",
  "Grit is different because it tells us that perfection isn't the goal.",
  "Grit lifts the unreasonable expectations off our shoulders.",
  "Grit tells us that the door is open wider than we first thought possible.",
  "Grit allows us to redefine our goals.",
  "Think about it: what's something you've always wanted to do, but gave up because you \"don't have the skills for it\"?",
  "What's something you love but aren't good at?",
  "The real workings of grit are to have sustainable passion and continue to try.",
  "Effort means more than your natural ability.",
  "Even if you haven't mastered a skill, grit tells you that you can still succeed if you can transform your passion into action.",
  "In a way, Duckworth is giving new hope to people who have shut the doors on their dreams.",
  "She is saying it is possible that you can accomplish anything.",
  "If at first you fail, then try one more time with grit.",
] as const;

const q46 = question(46, "What do we learn from new research about pandas?", "D", "New research suggests that pandas may be at risk of dying out because they are too comfortable.", [["A", "They are losing habitat due to the building of roads and houses."], ["B", "They have stopped seeking new mates for reproduction."], ["C", "They may not adapt to the fragmentation of their habitat."], ["D", "They may cease to exist as a result of enjoying too good a life."]]);
const q47 = question(47, "What can we conclude from the new research by scientists at Michigan State University?", "A", "New research suggests that pandas may be at risk of dying out because they are too comfortable.", [["A", "Environmentalists' long-time belief regarding panda conservation may be misleading."], ["B", "Housing development near pandas' homes may threaten their survival."], ["C", "Pandas' natural habitats are becoming less suitable for reproduction."], ["D", "The increased panda population is attributed to the fragmentation of their habitat."]]);
const q48 = question(48, "What is the experts' conclusion regarding pandas?", "C", "New research suggests that pandas may be at risk of dying out because they are too comfortable.", [["A", "It is urgent to provide an ideal habitat for them to thrive."], ["B", "It is very important to preserve their genetic diversity."], ["C", "Their chances of finding new mates have a lot to do with their habitat."], ["D", "Their environment for survival has been continuously worsening."]]);
const q49 = question(49, "What can we infer from the passage about the Goldilocks principle?", "B", "New research suggests that pandas may be at risk of dying out because they are too comfortable.", [["A", "It needs to be confirmed by more studies on pandas."], ["B", "It applies to the preservation of pandas too."], ["C", "It has implications for future panda research."], ["D", "It can be used to locate the right spot for pandas."]]);
const q50 = question(50, "What can the new findings do according to Professor Sillero?", "C", "New research suggests that pandas may be at risk of dying out because they are too comfortable.", [["A", "Help discover new ways for the conservation of pandas."], ["B", "Help remove pandas from the list of endangered species."], ["C", "Shed light on the conservation of most large meat-eating animals."], ["D", "Show the complexity of interactions between humans and animals."]]);
const q51 = question(51, "What does the passage say about people born with natural talents?", "A", "With those born with natural talents, it feels as if they excel without really trying.", [["A", "They seem to outdo others without hard work."], ["B", "They appear to know all the secrets to success."], ["C", "They feel it only too logical to succeed."], ["D", "They are bound to excel effortlessly."]]);
const q52 = question(52, "What does Duckworth say about talent?", "C", "With those born with natural talents, it feels as if they excel without really trying.", [["A", "It is a new concept much too overrated."], ["B", "It proves necessary for big achievements."], ["C", "It plays a lesser role in one's success."], ["D", "It is a guarantee for real success in life."]]);
const q53 = question(53, "What does the passage say about people thinking of attaining success?", "B", "With those born with natural talents, it feels as if they excel without really trying.", [["A", "They are puzzled how to present their best to the employer."], ["B", "They are burdened by their expectation of perfection."], ["C", "They will try hard to land a job that fits their skills best."], ["D", "They will find themselves lacking in all the skills they need."]]);
const q54 = question(54, "How does the author think grit can be helpful to us?", "D", "With those born with natural talents, it feels as if they excel without really trying.", [["A", "It allows us to know what we are good at."], ["B", "It opens our eyes to new opportunities."], ["C", "It focuses our attention on what we do."], ["D", "It lets us reconsider the goals to achieve."]]);
const q55 = question(55, "What message does Duckworth try to convey in her book Grit?", "B", "With those born with natural talents, it feels as if they excel without really trying.", [["A", "We should perfect ourselves to ensure success."], ["B", "We should stay persistent even in face of failures."], ["C", "We can never master a skill without constant practice."], ["D", "We can never expect to reach our goals without passion."]]);

